/*
 * A041200  Numerators of continued fraction convergents to sqrt(111).
 * https://oeis.org/A041200
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 8, u32 n <= 19, u64 n <= 41, u128 n <= 83,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  a(n) = numerators of continued‑fraction convergents to sqrt(111)
 *  a(n) = 590*a(n-6) – a(n-12)   for n >= 12
 *  The first 12 terms (n = 0 … 11) are generated by the continued‑fraction
 *  algorithm for sqrt(111) and are then used as the initial values for the
 *  linear recurrence.
 */

#include <stdlib.h>

/*  ----  global cache  ----  */
static seq_t *cache    = NULL;   /* cache[0..cache_len-1] holds a(i)          */
static idx_t cache_len = 0;       /* number of values currently cached        */

/*  ----  initialise cache with first 12 terms  ----  */
static void init_cache(void)
{
    if (cache_len > 0) return;          /* already initialised */

    /*  Continued fraction of sqrt(111)  */
    const idx_t D = 111;                /* the square‑free part               */
    idx_t      a0   = (idx_t)10;        /* floor(sqrt(111)) = 10              */
    idx_t      m    = 0;                /* m_0 = 0                            */
    idx_t      d    = 1;                /* d_0 = 1                            */
    idx_t      a    = a0;               /* a_0                               */

    /*  Recurrence for convergent numerators  */
    seq_t  p_nm2 = 0;   /* p_{-2} */
    seq_t  p_nm1 = 1;   /* p_{-1} */

    /*  Allocate cache for 12 terms  */
    cache_len = 12;
    cache = (seq_t *)malloc(sizeof(seq_t) * cache_len);
    if (cache == NULL) abort();          /* out of memory */

    for (idx_t i = 0; i < 12; ++i)
    {
        /*  Compute p_i = a_i * p_{i-1} + p_{i-2}  */
        seq_t ai_seq = (seq_t) a;
        seq_t ai_mul = ai_seq * p_nm1;
        seq_t pi = ai_mul + p_nm2;
        cache[i] = pi;

        /*  Prepare next continued‑fraction coefficient a_{i+1}  */
        if (i == 11) break;              /* we already stored term 11 */
        idx_t m_next   = d * a - m;                 /* m_{k+1} = d_k * a_k - m_k */
        idx_t d_next   = (D - m_next * m_next) / d; /* d_{k+1} = (D - m_{k+1}^2)/d_k */
        idx_t a_next   = (a0 + m_next) / d_next;    /* a_{k+1} = floor((a0 + m_{k+1})/d_{k+1}) */

        /*  Shift for next iteration  */
        m = m_next;  d = d_next;  a = a_next;
        p_nm2 = p_nm1;
        p_nm1 = pi;
    }
}

/*  ----  public function  ----  */
seq_t a(idx_t n)
{
    init_cache();            /* ensures cache[0..11] are set */

    if (n < cache_len) return cache[n];

    /*  Extend cache until it contains a(n)  */
    while (cache_len <= n)
    {
        /*  a(k) = 590*a(k-6) – a(k-12)  */
        const seq_t mult590 = (seq_t)590u;
        seq_t val = cache[cache_len - 6] * mult590;
        val -= cache[cache_len - 12];

        /*  Allocate one more slot  */
        seq_t *tmp = (seq_t *)realloc(cache, sizeof(seq_t) * (cache_len + 1));
        if (tmp == NULL) abort();          /* out of memory */
        cache = tmp;
        cache[cache_len] = val;
        ++cache_len;
    }
    return cache[n];
}
